// HasRoleAssignments applies the HasEdge predicate on the "role_assignments" edge.
func HasRoleAssignments() predicate.CustomUser {
	return predicate.CustomUser(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RoleAssignmentsTable, RoleAssignmentsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRoleAssignmentsWith applies the HasEdge predicate on the "role_assignments" edge with a given conditions (other predicates).
func HasRoleAssignmentsWith(preds ...predicate.UserRoleAssignment) predicate.CustomUser {
	return predicate.CustomUser(func(s *sql.Selector) {
		step := newRoleAssignmentsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CustomUser) predicate.CustomUser {
	return predicate.CustomUser(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CustomUser) predicate.CustomUser {
	return predicate.CustomUser(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CustomUser) predicate.CustomUser {
	return predicate.CustomUser(sql.NotPredicates(p))
}
